def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (everything after +)
        if '+' in v:
            v_no_build = v.split('+')[0]
        else:
            v_no_build = v

        # Split pre-release (everything after -)
        if '-' in v_no_build:
            parts = v_no_build.split('-', 1)
            core = parts[0]
            prerelease = parts[1]
        else:
            core = v_no_build
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        core_parts = core.split('.')
        major = int(core_parts[0])
        minor = int(core_parts[1]) if len(core_parts) > 1 else 0
        patch = int(core_parts[2]) if len(core_parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            prerelease_identifiers = prerelease.split('.')
            # Convert identifiers to tuples for comparison
            parsed_identifiers = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    parsed_identifiers.append((0, int(identifier)))
                else:
                    parsed_identifiers.append((1, identifier))
        else:
            parsed_identifiers = None

        return (major, minor, patch, prerelease_identifiers if prerelease else None, parsed_identifiers)

    def sort_key(v):
        major, minor, patch, prerelease_str, parsed_identifiers = parse_version(v)

        # For sorting:
        # - Compare major, minor, patch numerically
        # - If pre-release exists, it sorts before release (use False for prerelease, True for release)
        # - Pre-release identifiers are compared according to rules
        # - Build metadata is ignored

        if parsed_identifiers is None:
            # No pre-release: sorts after any pre-release of the same version
            return (major, minor, patch, (1,))
        else:
            # Has pre-release: sorts before any release of the same version
            return (major, minor, patch, (0, tuple(parsed_identifiers)))

    # Use stable sort to maintain input order for equal precedence
    return sorted(versions, key=sort_key)

